av21_orivelle_circuit.script:
// A four-day circuit. Native NPC placement, not a player travel command.
const npc = 'Orivelle';
const health = check({type:'npc-health',npc});
const locked = storage.av21_orivelle_roaming_paused === true;
if (locked || (typeof health === 'number' && health <= 0) ||
    check({type:'npc-in-party',npc}) === true ||
    check({type:'npc-in-combat',npc}) === true ||
    check({type:'npc-in-scene',npc}) === true) {
  skip = true;
} else {
  const dayValue = Number(check({type:'day'}));
  const day = Number.isFinite(dayValue) && dayValue >= 1 ? Math.floor(dayValue) : 1;
  const route = [
    ['Mythwing Meadows','Mythwing Meadows - Return Hide'],
    ['Rimeglass Crown','Rimeglass Crown - Summit Saddle'],
    ['Mirrorwater Basin','Mirrorwater Basin - Rim Watch'],
    ['Prismbloom Basin','Prismbloom Basin - Mineral Shore']
  ];
  const index = (day - 1) % route.length;
  const destination = route[index];
  const here = check({type:'npc-location',npc});
  const area = check({type:'npc-area',npc});
  if (storage.av21_orivelle_route_day === day ||
      (here === destination[0] && area === destination[1])) {
    storage.av21_orivelle_route_day = day;
    skip = true;
  } else {
    effects.push({type:'npc-placement',npc,operation:'moveTo',location:destination[0],area:destination[1]});
    storage.av21_orivelle_route_day = day;
    storage.av21_orivelle_route_index = index;
  }
}

gh_daily_resource_recovery.script:
const day = check({type:'day'});
const previous = storage.ghRecoveryLastDay;
if (!Number.isFinite(day) || day < 1) {
  skip = true;
} else if (!Number.isFinite(previous)) {
  storage.ghRecoveryLastDay = day;
  skip = true;
} else if (day <= previous) {
  skip = true;
} else {
  storage.ghRecoveryLastDay = day;
  effects.push({type:'story',instruction:'The actual party day counter has advanced. This is the one daily normal-recovery cue: restore Mana and Stamina to each living player character actual current maximum through the supported resource update, unless a completed rest or another supplied update already filled it for this transition. Do not restore either resource again on later turns of this day. This is resource recovery, not healing, resurrection, removal of soul shock, forced travel, or permission to choose the player activities.'});
}

cp_clock_and_prison_release.script:
const players=Object.keys(check({type:'player-level'})||{}); if(players.length!==1){skip=true;}else{
const tick=Number(check({type:'game-tick'}))||0;
const realm=check({type:'party-realm'});
const counts=check({type:'player-item',item:'Wanted Poster'})||{};
const held=Number(counts[players[0]])||0;
const custody=check({type:'read-boolean',key:'gh_in_custody'})===true;
const role=check({type:'read-string',key:'gh_prison_role'});
if(realm==='Wraith Island Prison'){
 storage.cp_pending=false;storage.gh_prison_wanted=false;
 if(held>0)effects.push({type:'item-remove',item:'Wanted Poster',quantity:held,target:'allPlayers'});
 if(custody&&role==='prisoner'){
  if(!Number.isFinite(storage.cp_entry_tick)){
   storage.cp_entry_tick=tick;storage.cp_last_prison_tick=tick;storage.cp_prison_count=0;
  }else if(tick>storage.cp_entry_tick&&storage.cp_last_prison_tick!==tick){
   storage.cp_prison_count=(Number(storage.cp_prison_count)||0)+1;storage.cp_last_prison_tick=tick;
  }
  if(storage.cp_prison_count>=15){
storage.gh_in_custody=false; storage.gh_prison_role='';
storage.gh_prison_wanted=false; storage.gh_prison_order=false;
storage.gh_prison_departed=true; storage.cp_pending=false;
storage.cp_prison_count=0; storage.cp_entry_tick=null;
storage.cp_last_prison_tick=null; storage.cp_release_tick=tick;
effects.push({type:'party-location',operator:'set',value:'City Guard Headquarters'},
 {type:'party-area',operator:'set',value:'City Guard Headquarters - Public Entry'},
 {type:'npc-placement',npc:'allPartyNPCs',operation:'moveTo',location:'City Guard Headquarters',area:'City Guard Headquarters - Public Entry'},
 {type:'story',instruction:'After some time, the short custodial term ends. You are released and returned to the public entrance of Glowhaven City Guard Headquarters. Preserve actual belongings, injuries and established companions; do not grant money or replacement equipment. This automatic wanted case is closed. Continue from the actual return location without demanding a new application or another sentence for the same incident.'});
  }
 }
}else{
 if(!custody){storage.cp_entry_tick=null;storage.cp_last_prison_tick=null;storage.cp_prison_count=0;}
 if(storage.cp_pending===true&&tick>=Number(storage.cp_due_tick)){
  storage.cp_pending=false;
  if(held<=0){effects.push({type:'item-add',item:'Wanted Poster',quantity:1,target:'allPlayers'},
   {type:'story',instruction:'A creased wanted poster has found its way among your belongings. Your own face is printed on it. Let the discovery happen naturally; do not expose flags, trigger logic or an invisible police meter.'});}
 }
}
// Possession is the only automatic-enforcement switch. No reissue on discard.
if(held<=0&&!storage.cp_pending){storage.cp_next_demand_tick=0;}
}

cp_guard_arrest_attempt.script:
const players=Object.keys(check({type:'player-level'})||{}); if(players.length!==1){skip=true;}else{
const tick=Number(check({type:'game-tick'}))||0;
if(tick<Number(storage.cp_next_demand_tick||0)){skip=true;}else{
 const named=["Nao Tsukuda", "Daisuke Mochida", "Ayaka Naruse", "Tetsuya Ōmi"];
 const types=check({type:'npc-type',npc:'anySceneNPC'})||{};
 const present=Object.keys(types).filter(n=>types[n]==='City Guard'||named.includes(n));
 let officer=present.find(n=>Number(check({type:'npc-health',npc:n}))>0&&!check({type:'npc-in-party',npc:n}));
 if(!officer&&["Main City Gate", "East City Gate", "West City Gate", "City Guard Headquarters", "Four Sages Bazaar", "Merchant's Row", "Whitecrest Harbor", "Cloud District", "The Grand Approach", "The Grand Ascent", "The Eternal Crucible", "Crooked Tankard", "Roseberry Inn", "The Golden Ladle", "The Jade Cup Teahouse", "The Everlight Public Library", "Adventurer's Guild - Glowhaven Branch", "Caravan Outpost"].includes(check({type:'party-location'}))){
  officer=named.find(n=>Number(check({type:'npc-health',npc:n}))>0&&!check({type:'npc-in-combat',npc:n})&&!check({type:'npc-in-party',npc:n})&&!check({type:'npc-in-scene',npc:n}));
  if(officer)effects.push({type:'npc-placement',npc:officer,operation:'moveHere'});
 }
 if(!officer){skip=true;}else{
  storage.cp_next_demand_tick=tick+4;
  effects.push({type:'story',instruction:officer+' recognizes the wanted face and leads a patrol demand to stop and surrender. Establish an approaching patrol, not unexplained instant capture. The suspect can answer, flee or resist. Use actual nonlethal arrest tactics and real combat outcomes; no invulnerable officers, free damage or prison teleport while undefeated. Do not arrest innocent companions.'});
 }
}
}

cp_arrest_and_transport.script:
const players=Object.keys(check({type:'player-level'})||{}); if(players.length!==1){skip=true;}else{
const types=check({type:'npc-type',npc:'anySceneNPC'})||{};
const named=["Nao Tsukuda", "Daisuke Mochida", "Ayaka Naruse", "Tetsuya Ōmi"];
const actual=Object.keys(types).some(n=>(types[n]==='City Guard'||named.includes(n))&&Number(check({type:'npc-health',npc:n}))>0);
if(!actual){skip=true;}else{
 const tick=Number(check({type:'game-tick'}))||0;
 storage.gh_in_custody=true;storage.gh_prison_role='prisoner';storage.gh_prison_wanted=false;
 storage.cp_pending=false;storage.cp_entry_tick=tick;storage.cp_last_prison_tick=tick;storage.cp_prison_count=0;
 effects.push({type:'known-entity',entity:'Wraith Island Prison',operator:'set',value:true},
  {type:'known-entity',entity:'Wraith Island Custody District',operator:'set',value:true},
  {type:'known-entity',entity:'Intake and Property Office',operator:'set',value:true},
  {type:'party-location',operator:'set',value:'Intake and Property Office'},
  {type:'party-area',operator:'set',value:'Intake and Property Office - Processing Desk'},
  {type:'npc-placement',npc:'allPartyNPCs',operation:'moveTo',location:'Intake and Property Office',area:'Intake and Property Office - Processing Desk'},
  {type:'story',instruction:'Following the actual surrender or resolved capture, compress the guarded transfer and intake at Wraith Island Prison. You are serving a short custodial term. Keep belongings intact rather than inventing a seizure/replacement system; no automatic fine. Staff offer ordinary conversation, work or waiting, and casually explain that you can choose to serve the remainder quietly. Do not create a compulsory prison quest or arrest the uninvolved companions. Accompanying party NPCs arrive as escorted visitors or witnesses, not co-defendants or inmates. Preserve their actual agency and existing obligations; do not put them in cells or give them the player’s sentence.'});
 }
}

