ad34_scene_dispatch.script:
const jobs = [{"title": "Borrowed After the Applause", "source": "Adoha Aonuma", "location": "Four Sages Bazaar", "level": 1}, {"title": "A Stable Fit for Old Bones", "source": "Ragnar Leonhart", "location": "Whitepass Caravan Lodge", "level": 1}, {"title": "Three Rhymes Behind", "source": "Karia Morino", "location": "Crooked Tankard", "level": 1}, {"title": "The Map Has Your Footprints", "source": "Renpei Sugita", "location": "Adventurer's Guild - Glowhaven Branch", "level": 6}, {"title": "A Handle Worth Keeping", "source": "Tetsuya Kanamori", "location": "Adventurer's Guild - Glowhaven Branch", "level": 4}, {"title": "The Quiet Room", "source": "Nae Komorida", "location": "Willowbend Residential District", "level": 1}, {"title": "Prison: A Dry Line Tomorrow", "source": "Masaru Hasebe", "location": "Prison Work Yard", "level": 1}, {"title": "Prison: The Book Returns", "source": "Akira Oritsu", "location": "Prison Records Office", "level": 1}];
const location = check({type:'party-location'});
const actions = check({type:'action-text'});
const text = (Array.isArray(actions) ? actions : [actions]).join(' ');
const levels = Object.values(check({type:'player-level'}) || {}).filter(x=>typeof x==='number' && x>0);
const minLevel = levels.length ? Math.min(...levels) : 1;
storage.ad34_solo = levels.length === 1;
storage.ad34_offer_target = '';
const propertyWords = /\b(rent|lease|purchase|buy|bought|rented|own|ownership|deed|lodging|room|workshop|house|property|key)\b/i.test(text);
storage.ad34_property_interest = propertyWords;
const candidates = jobs.filter(j => j.location === location &&
  check({type:'quest-status',questId:j.title}) === 'hidden' &&
  check({type:'npc-in-scene',npc:j.source}) === true &&
  minLevel + 2 >= j.level);
const explicit = candidates.find(j=>text.toLowerCase().includes(j.title.toLowerCase()));
const addressed = candidates.find(j=>text.toLowerCase().includes(j.source.toLowerCase()) || text.toLowerCase().includes(j.source.split(' ')[0].toLowerCase()));
const recent = String(check({type:'story-text'}) || '');
const followup = /\b(yes|sure|okay|ok|accept|agree|terms|pay|payment|do that|i will|i'll)\b/i.test(text) &&
  candidates.find(j=>recent.toLowerCase().includes(j.title.toLowerCase()));
if (/\b(job|work|help|request|commission|task|posting|offer|problem|repair)\b/i.test(text) || explicit || followup) {
  const choice = explicit || followup || addressed || (candidates.length === 1 ? candidates[0] : null);
  if (choice) storage.ad34_offer_target = choice.title;
}
// Older Canopy offers share a venue. Expose only the current conversation's job.
const legacy = [{"title": "A Road Made of Air: The Far End", "source": "Sakuya Tomonari", "words": "crossing|route|tether|road made"}, {"title": "The Hunt That Looks Back: A Shape in the Wake", "source": "Sakuya Tomonari", "words": "hunt|predator|shape.*wake"}, {"title": "First Bloom, Last Rehearsal", "source": "Sakuya Tomonari", "words": "bloom|rehearsal|celebration"}, {"title": "A Voice Below the Roots", "source": "Sakuya Tomonari", "words": "roots|voice|hum"}, {"title": "What the Manta Leaves", "source": "Sakuya Tomonari", "words": "manta|shed|comb"}, {"title": "The Room Below the Ring", "source": "Kureha Kazahana", "words": "orrery|drown|ring"}, {"title": "An Impossible Shade of Green", "source": "Kureha Kazahana", "words": "shade|green|pigment"}, {"title": "Two Teams, One Clean Sample", "source": "Kureha Kazahana", "words": "rival|teams|clean sample"}];
storage.ad34_legacy_offer = '';
if (location === 'Asterveil Canopy') {
  const available = legacy.filter(j=>check({type:'npc-in-scene',npc:j.source}) === true &&
    !['accepted','completed'].includes(check({type:'quest-status',questId:j.title})));
  const named = available.find(j=>text.toLowerCase().includes(j.title.toLowerCase())) ||
    available.find(j=>recent.toLowerCase().includes(j.title.toLowerCase()));
  const relevant = available.find(j=>new RegExp(j.words,'i').test(text));
  const chosen = named || relevant || (/\b(job|work|help|request|offer)\b/i.test(text) && available.length ? available[0] : null);
  if (chosen) storage.ad34_legacy_offer = chosen.title;
}

ad34_quest_repair.script:
const raw = check({type:'action-text'});
const inputs = Array.isArray(raw) ? raw : [raw];
const seen = [];
for (const input of inputs) {
  // Match only the whole out-of-character command, never a quotation inside prose.
  const match = /^\s*quest done:\s*([^\r\n]+?)\s*$/i.exec(String(input || ''));
  if (!match) continue;
  const title = match[1];
  if (seen.includes(title)) continue;
  seen.push(title);
  const status = check({type:'quest-status',questId:title});
  if (status !== 'accepted') {
    effects.push({type:'story',instruction:'Out of character only: the quest-repair command found no accepted quest with the exact supplied name. Give one short correction note without quoting internal flags. Do not change a quest, item, reward or NPC memory, and continue the current scene.'});
  } else {
    effects.push({type:'quest-complete',questId:title});
    effects.push({type:'story',instruction:'The player used the out-of-character journal repair for '+title+'. Let its normal completion effects settle once. Continue the existing scene; NPCs did not hear a command and no fictional deed, forged evidence or extra payment is retroactively invented.'});
  }
  if (effects.length >= 8) break;
}
if (!effects.length) skip = true;

ad34_touring_cast.script:
// The build replaces {"Ragnar Leonhart": [["The Eternal Crucible", "The Eternal Crucible - Arena Floor"], ["Crooked Tankard", "Crooked Tankard - Hearth Corner"], ["The Cinder Pit", "The Cinder Pit - Fighting Floor"], ["Whitepass Caravan Lodge", "Whitepass Caravan Lodge - Common Hearth"], ["Cloudbloom Landing", "Cloudbloom Landing - Crossing Quay"], ["Asterveil Canopy", "Asterveil Canopy - Guest Terrace"], ["The Eternal Crucible", "The Eternal Crucible - Competitor Passage"], ["Roseberry Inn", "Roseberry Inn - Common Room"]], "Adoha Aonuma": [["Four Sages Bazaar", "Four Sages Bazaar - Four Sages Fountain"], ["The Jade Cup Teahouse", "The Jade Cup Teahouse - Tea Room"], ["Snowbell Playhouse", "Snowbell Playhouse - Stage and Wings"], ["The Copper Ram", "The Copper Ram - Musicians' Corner"], ["Asterveil Canopy", "Asterveil Canopy - Guest Terrace"], ["Asterveil Canopy", "Asterveil Canopy - Guest Boughs"], ["Roseberry Inn", "Roseberry Inn - Common Room"], ["Four Sages Bazaar", "Four Sages Bazaar - North Arcade"]], "Karia Morino": [["Adventurer's Guild - Glowhaven Branch", "Adventurer's Guild - Glowhaven Branch - Training Yard"], ["Crooked Tankard", "Crooked Tankard - Taproom"], ["Whitepass Caravan Lodge", "Whitepass Caravan Lodge - Route Desk"], ["The Copper Ram", "The Copper Ram - Taproom"], ["Rimeglass Refuge", "Rimeglass Refuge - Common Shelter"], ["Reedglass Anchorage", "Reedglass Anchorage - Arrival Deck"], ["Heatherwatch Shelf", "Heatherwatch Shelf - Common Room"], ["Asterveil Canopy", "Asterveil Canopy - Guest Terrace"]]} with exact supported location/area pairs.
const routes = {"Ragnar Leonhart": [["The Eternal Crucible", "The Eternal Crucible - Arena Floor"], ["Crooked Tankard", "Crooked Tankard - Hearth Corner"], ["The Cinder Pit", "The Cinder Pit - Fighting Floor"], ["Whitepass Caravan Lodge", "Whitepass Caravan Lodge - Common Hearth"], ["Cloudbloom Landing", "Cloudbloom Landing - Crossing Quay"], ["Asterveil Canopy", "Asterveil Canopy - Guest Terrace"], ["The Eternal Crucible", "The Eternal Crucible - Competitor Passage"], ["Roseberry Inn", "Roseberry Inn - Common Room"]], "Adoha Aonuma": [["Four Sages Bazaar", "Four Sages Bazaar - Four Sages Fountain"], ["The Jade Cup Teahouse", "The Jade Cup Teahouse - Tea Room"], ["Snowbell Playhouse", "Snowbell Playhouse - Stage and Wings"], ["The Copper Ram", "The Copper Ram - Musicians' Corner"], ["Asterveil Canopy", "Asterveil Canopy - Guest Terrace"], ["Asterveil Canopy", "Asterveil Canopy - Guest Boughs"], ["Roseberry Inn", "Roseberry Inn - Common Room"], ["Four Sages Bazaar", "Four Sages Bazaar - North Arcade"]], "Karia Morino": [["Adventurer's Guild - Glowhaven Branch", "Adventurer's Guild - Glowhaven Branch - Training Yard"], ["Crooked Tankard", "Crooked Tankard - Taproom"], ["Whitepass Caravan Lodge", "Whitepass Caravan Lodge - Route Desk"], ["The Copper Ram", "The Copper Ram - Taproom"], ["Rimeglass Refuge", "Rimeglass Refuge - Common Shelter"], ["Reedglass Anchorage", "Reedglass Anchorage - Arrival Deck"], ["Heatherwatch Shelf", "Heatherwatch Shelf - Common Room"], ["Asterveil Canopy", "Asterveil Canopy - Guest Terrace"]]};
const dayRaw = Number(check({type:'day'}));
const day = Number.isFinite(dayRaw) && dayRaw >= 1 ? Math.floor(dayRaw) : 1;
const time = String(check({type:'time-of-day'}) || '').toLowerCase();
const late = /afternoon|evening|night|dusk/.test(time);
for (const [npc, stops] of Object.entries(routes)) {
  const hp = check({type:'npc-health',npc});
  if ((storage.cc1_active && storage.cc1 && (storage.cc1.roster||[]).includes(npc)) || typeof hp !== 'number' || hp <= 0 || storage['ad34_hold_'+npc] === true ||
      check({type:'npc-in-party',npc}) === true ||
      check({type:'npc-in-combat',npc}) === true ||
      check({type:'npc-in-scene',npc}) === true) continue;
  const index = ((day - 1) * 2 + (late ? 1 : 0)) % stops.length;
  const [location,area] = stops[index];
  if (check({type:'npc-location',npc}) === location && check({type:'npc-area',npc}) === area) continue;
  // At most one move per traveler in a phase; never a player teleport or a new NPC.
  effects.push({type:'npc-placement',npc,operation:'moveTo',location,area});
}

ad34_public_opportunities.script:
const entries = [{"id":"q0","location":"Phoenix Wing Academy","quest":"A Formula Worth Selling","text":"Ranka Kagari is trying to arrange a small recovery-formula trial; somebody at the faculty table is asking why two dosage sheets disagree.","level":1},{"id":"q1","location":"Gryffin Tail Academy","quest":"One Standard, Two Students","text":"Two students compare reassessment notices with different requirements for what appears to be the same exercise.","level":1},{"id":"q2","location":"Dragon Hoard Academy","quest":"The Shield's Late Return","text":"A student complains that a loaned shield has not come back to Mai Kajiwara's repair queue.","level":1},{"id":"q3","location":"Hydra Head Academy","quest":"What the Scent Becomes","text":"People near Kaoruko Hanazono's workroom are arguing about a fragrance batch that changed after leaving the bench.","level":1},{"id":"q4","location":"Rune and Raven's","quest":"The Wrong Kind of Light","text":"A customer asks Rui Takatori why a purchased light does not behave like the demonstration.","level":1},{"id":"q5","location":"Whitecrest Harbor","quest":"A Crate Without a Signature","text":"At the cargo pier, a delivery is waiting because nobody has matched it to an actual accepting party.","level":1},{"id":"q6","location":"Glowhaven Farmlands","quest":"Water Owed Downstream","text":"Growers downstream are comparing the water reaching their irrigation runs with what their neighbors expected.","level":1},{"id":"q7","location":"Four Sages Bazaar","quest":"A Fair Measure","text":"Two traders are checking the same weight on different scales, drawing a small but interested audience.","level":1},{"id":"q8","location":"The Everlight Public Library","quest":"Margins in Two Hands","text":"A reader has noticed two different hands making incompatible notes in a much-consulted text.","level":1},{"id":"q9","location":"The Eternal Crucible","quest":"Before the First Bell","text":"A practice entrant has been told to arrive early, and is trying to find out which part of the preparation actually matters.","level":1},{"id":"q10","location":"Snowbell Playhouse","quest":"The Premiere Was Yesterday","text":"A tired performer at Snowbell Playhouse is comparing the advertised opening date with the rehearsal everyone actually attended.","level":1},{"id":"q11","location":"The Cinder Pit","quest":"The Cinder Pit Rematch","text":"A previous bout is still being argued about at the booking desk, and somebody wants a properly arranged rematch.","level":1},{"id":"q12","location":"Snowmelt Residential Steps","quest":"Room for One More Bench","text":"Neighbors are measuring a shared landing and disagreeing about whether another bench would help or block the way.","level":1},{"id":"q13","location":"Woolridge Pastures","quest":"Tracks Beside the Fold","text":"A herder has marked unfamiliar tracks near the winter fold and wants a sound explanation before moving the animals.","level":1},{"id":"q14","location":"Asterveil Canopy","quest":"First Bloom, Last Rehearsal","text":"A celebration rehearsal and the first flowering work both need the same stretch of shared Canopy space.","level":1},{"id":"q15","location":"Rimeglass Crown","quest":"What the Manta Leaves","text":"Expeditioners compare a shed comb fragment with the immense filter feeders seen riding the mountain's lee currents.","level":1},{"id":"q16","location":"Bellwind Conservatory","quest":"Cuts Among the Pollen","text":"A conservatory worker is examining a damaged pollen screen while two colleagues disagree about how it happened.","level":1},{"id":"q17","location":"Prison Records Office","quest":"A Date in the Ledger","text":"An authorized records visitor asks why two dates in the same case file do not agree. This is public counter business, not access to the secure archive.","level":1},{"id":"winter","location":"Whitepass Caravan Lodge","quest":"","level":25,"text":"Daigo Kisaragi's Bellwether Company has returned with frost samples and no confident reading of them. They need help tracing the unnatural cold from Coldglass Galleries; their martial experience has stopped being enough."},{"id":"thesis","location":"Asterveil Canopy","quest":"","level":25,"text":"Suzuha Midorise is looking for help finding the Stillwind Pearl after her guild posting attracted no volunteers. She has measurements, stubborn hope and very little ability to defend herself in the wild."},{"id":"laurels","location":"Tetherroot Chain","quest":"","level":25,"text":"An expeditioner is complaining that the Copper Laurels demanded a recovery fee for a prize they never helped recover. Another traveler has heard the same boast at a different crossing."}];
const tick = Number(check({type:'game-tick'}));
const location = check({type:'party-location'});
const sceneCombat = check({type:'npc-in-combat',npc:'anySceneNPC'});
const fighting = sceneCombat === true || (sceneCombat && typeof sceneCombat === 'object' && Object.values(sceneCombat).some(Boolean));
const actions = check({type:'action-text'});
const input = (Array.isArray(actions) ? actions : [actions]).join(' ');
const arrival = storage.ad34_last_place !== location;
storage.ad34_last_place = location;
// Nothing here asks the AI a question. Cooldown and cleared-job filters run in JS.
if (fighting || tick < 3 || tick - Number(storage.ad34_last_public_tick ?? -100) < 9 ||
    /quest done:|\b(attack|cast|fight|sleep|rest|kiss|rent|buy|purchase|leave|portal|return home)\b/i.test(input) ||
    !(arrival || /\b(look around|news|rumou?r|listen|notice|explore|anything happening|what.*do here)\b/i.test(input))) {
  skip = true;
} else {
  const levels = Object.values(check({type:'player-level'}) || {}).filter(x=>typeof x==='number' && x>0);
  const level = levels.length ? Math.min(...levels) : 1;
  const choices = entries.filter(e => e.location === location && !storage['ad34_public_'+e.id] &&
    level >= (e.level || 1) && (!e.quest || check({type:'quest-status',questId:e.quest}) === 'hidden'));
  if (!choices.length) skip = true;
  else {
    const e = choices[Number(storage.ad34_public_cursor || 0) % choices.length];
    effects.push({type:'story',instruction:e.text+' Present one brief public circumstance at this actual location only if the scene has room. No acceptance, journal entry, revealed private motive or completed job follows from overhearing it. If the player ignores it, continue their chosen activity.'});
    storage['ad34_public_'+e.id] = true;
    storage.ad34_public_cursor = Number(storage.ad34_public_cursor || 0) + 1;
    storage.ad34_last_public_tick = tick;
  }
}

ad34_returning_clients.script:
const contacts=[
 ['Guild: Boars at the Watercourse',"Adventurer's Guild - Glowhaven Branch",'Komugi Hanabishi'],
 ['The Wrong Kind of Light',"Rune and Raven's",'Rui Takatori'],
 ['Tracks Beside the Fold','Woolridge Pastures','Haruto Aonuma']
];
