const finishField=()=>{settleNPC();const last=c.rounds?.at(-1)?.[0];c.champion=last?.done?(last.winner==='@'?c.entrant:last.winner):null;};
const care=m=>{c.care[c.edition+':'+m.id+':'+m.startedTick]={owner:c.entrant,edition:c.edition};const h=health(m.opponent);if(check({type:'npc-location',npc:m.opponent})===venue&&typeof h==='number'&&typeof m.opponentStartHealth==='number'&&h<m.opponentStartHealth)effects.push({type:'npc-health',npc:m.opponent,operator:'set',value:m.opponentStartHealth});};
const close=(outcome,reason)=>{c.phase='closed';c.outcome=outcome;c.closedTick=tick;storage.gh_lore_tournament_active=false;if(!c.exhibition){c.nextTick=tick+100;c.history.push({v:3,edition:c.edition,title:c.title,entrant:c.entrant,outcome,reason,champion:c.champion||null,closedTick:tick,rounds:JSON.parse(JSON.stringify(c.rounds||[])),card:JSON.parse(JSON.stringify(c.card))});c.history=c.history.slice(-8);}mirror();};
const finish=(winner,reason)=>{
const m=current();if(c.phase!=='live'||!m||typeof m.startedTick!=='number'||m.result)return;
m.result={winner,reason,tick};care(m);storage.gh_lore_tournament_active=false;
if(c.exhibition){close(winner==='player'?'exhibition win':winner==='draw'?'exhibition draw':'exhibition loss',reason);say('The friendly bout ends: '+reason+'. Offer appropriate optional care. No championship prize or cooldown.');return;}
recordNode(winner,reason);
if(winner!=='player'){finishField();close(reason==='voluntary withdrawal'?'withdrawn':'eliminated',reason);say('The entrant’s run ends: '+reason+'. Offer appropriate care. Officials abstract the remaining NPC bouts and record '+(c.champion?c.champion+' as champion':'no champion because the remaining field is unavailable')+'. Report recorded results without inventing extra player fights or a player prize.');return;}
if(node(m.node)===c.rounds.at(-1)[0]){finishField();c.prizes[c.edition]={owner:c.entrant,title:c.title,marks:c.purse};close('champion',reason);say(c.entrant+' wins '+c.title+'. '+c.purse+' marks and one trophy are owed for collection, not yet granted. No extra final. Offer appropriate optional rest or care.');}
else if(schedule()){c.phase='waiting';mirror();say('The bout is recorded. Other bracket results determine the next opponent. Offer care or rest without invented injuries or a full-bar requirement.');callNext();}
else{finishField();close('cancelled','no available next opponent');say('No fit opponent can fill the next round. The edition closes without inventing an unplayed final or awarding a trophy.');}
};
const withdraw=reason=>{const m=current();if(c.phase==='live'&&m&&typeof m.startedTick==='number'&&!m.result){finish('opponent',reason);return;}if(!active())return;if(!c.exhibition){recordNode('opponent',reason);finishField();}close('withdrawn',reason);say('The explicit forfeit ends the entry. '+(c.champion?'The remaining field concludes with '+c.champion+' as champion.':'No player prize is owed.'));};
if(!solo||c.entrant!==names[0]||c.phase!=='live'){skip=true;}
else{
const m=current();if(!m||typeof m.startedTick!=='number'||m.result){skip=true;}
else{
const p=playerHealth(),h=health(m.opponent),native=inRing(m)&&!m.requiresRuling;
if("draw"==='draw')finish('draw',"official simultaneous knockout");
else if(native&&typeof p==='number'&&p<=0&&typeof h==='number'&&h<=0)finish('draw','simultaneous knockout');
else if(native&&typeof p==='number'&&p<=0)finish('opponent','actual player incapacity in the ring');
else finish("draw","official simultaneous knockout");
}
mirror();
}
}

