const sites={"Pinewater River - Brookmeadow Ford":"r","Pinewater River - River Bend":"r","Saltmere - Village Landing":"h","Saltmere - Shoreline Green":"s","Whitecrest Harbor - Harbor Quay":"h","Whitecrest Harbor - Passenger Landing":"h","Driftstone Isle - Island Landing":"s","Driftstone Isle - Rocky Shore":"s","Pinewake Coast - Pineward Beach":"s","Pinewake Coast - Tide Pools":"s","The Gilded Albatross - Main Deck":"d","Moonarch Isle - Pebble Landing":"s","Moonarch Isle - Offshore Drop":"d","Stillback Isle - Quiet Landing":"s","Greenrush Estuary - Skiff Landing":"e","Greenrush Estuary - Reedwalk":"e","Gullwatch Reefs - Boat Shelf":"s","Gullwatch Reefs - Tide Pools":"s"},fish=[["Pinewater Perch","r",30,"clear",12,30],["Brookmeadow Roach","r",32,"overcast",8,22],["Millpond Crucian","r",25,"rain",12,32],["Willowback Trout","r",20,"overcast",18,42],["Button-Eyed Minnow","r",35,"clear",4,10],["Rainbell Loach","re",23,"rain",8,20],["Reedstripe Mullet","eh",28,"overcast",15,38],["Brackish Bream","e",27,"rain",16,35],["Mud-Sleeve Goby","eh",33,"overcast",5,16],["Greenrush Flounder","es",23,"fog",15,37],["Harbor Herring","hs",35,"overcast",14,27],["Lantern Sardine","hs",35,"clear",8,18],["Dockside Smelt","h",30,"rain",7,17],["Copper-Gill Mackerel","hsd",28,"wind",22,43],["Whitecrest Whiting","hs",28,"clear",18,36],["Pebble Sole","s",24,"clear",12,29],["Ribbon Garfish","sd",22,"wind",30,65],["Crescent Sea Bass","hsd",19,"overcast",25,62],["Silver-Tail Pollock","sd",25,"overcast",25,55],["Sandburrow Gurnard","s",22,"clear",18,38],["Glassvein Char","r",8,"clear",22,48],["Bottle-Green Tench","re",9,"rain",25,52],["Amberfin Eel","re",7,"rain",35,85],["Pearlspot Wrasse","s",9,"clear",15,32],["Blueglass Needlefish","sd",8,"wind",35,78],["Velvet Skate","sd",7,"fog",35,80],["Stormstripe Bonito","d",8,"wind",40,90],["Moonmirror Dace","re",2,"fog",18,34],["Lanternjaw Angler","d",2,"fog",35,70],["Crownfin Sailfish","d",2,"wind",95,180]];
const tick=Number(check({type:'game-tick'}))||0,area=String(check({type:'party-area'})||''),habitat=sites[area];
const baited=false,key=baited?'bait':'lure';
if(!storage.fshCasts||typeof storage.fshCasts!=='object')storage.fshCasts={};
if(check({type:'party-realm'})!=='Glowhaven'||!habitat||tick<=0||storage.fshCasts[key]===tick){skip=true}else{
 const zone=habitat==='r'?'inland':'coast';
 const weather=storage.fshWeather?.[zone]?.kind||(zone==='inland'?'clear':'overcast');
 if(weather==='storm'&&habitat==='d'){
  effects.push({type:'story',instruction:'Exposed offshore fishing is unsafe in this squall. Keep the line stowed and show the rough water; offer waiting or a genuinely sheltered fishing ground. No bait is spent and no catch is awarded. Do not move the player or summon a monster.'});
  storage.fshCasts[key]=tick;
 }else{
  const pool=fish.filter(f=>f[1].includes(habitat)&&(!storage.fshHook||f[2]>2));
  const weights=pool.map(f=>f[2]*(f[3]===weather?2.2:1)*(baited&&(f[2]<=9||/Loach|Bream|Tench|Eel|Goby/.test(f[0]))?1.6:1));
  let roll=Math.random()*weights.reduce((a,b)=>a+b,0),chosen=pool[pool.length-1];
  for(let i=0;i<pool.length;i++){roll-=weights[i];if(roll<0){chosen=pool[i];break}}
  const cm=chosen[4]+Math.floor(Math.random()*(chosen[5]-chosen[4]+1));
  // The same local shoal roll is shared by simultaneous qualifying anglers.
  // Native scope/conditions, not script-side text parsing, select the recipients.
  if(baited)effects.push({type:'item-remove',item:'Angler’s Bait Portion',quantity:1,target:'satisfyingPlayers'});
  if(chosen[2]===2){
   storage.fshHook={fish:chosen[0],cm,area,until:tick+6};
   effects.push({type:'player-traits',operator:'add',value:'Rare Fish on the Line',target:'satisfyingPlayers'});
   effects.push({type:'story',instruction:'A rare '+chosen[0]+' is hooked, not landed or acquired. Describe its distinctive movement and let the angler choose a response: ease the line and tire it, guide it away from cover, take a risk, or release it. One actual next handling attempt can settle the catch using Fishing. No mandatory wording, extra fight, automatic damaged tackle or inventory fish yet. Waiting for up to six turns is possible; leaving this fishing ground loses the line’s catch.'});
  }else{
   effects.push({type:'item-add',item:chosen[0],quantity:1,target:'satisfyingPlayers'});
   effects.push({type:'story',instruction:'The qualifying angler lands one '+chosen[0]+', about '+cm+' cm, in '+weather+' conditions. The inventory grant is already handled; do not duplicate it, invent another catch or add separate XP/resource rewards. A mixed action result can mean an awkward landing. Keep this a short fishing moment unless the player engages further.'});
   if(!storage.fshRecords||typeof storage.fshRecords!=='object')storage.fshRecords={};
   const old=storage.fshRecords[chosen[0]]||{best:0,landings:0};
   storage.fshRecords[chosen[0]]={best:Math.max(old.best,cm),landings:old.landings+1};
  }
  storage.fshCasts[key]=tick;
 }
}

